# -*- coding: utf-8 -*-
"""Crónicas do Sistema · Livro III: Os Dez Mundos (Guia de Mundo narrado)."""
from cr_a import P, ch, PROMPTS, CHAPTERS

ch('mundos', 'CAPÍTULO 17', 'Os Mundos que Falharam', 'lore_map', 'arenas/ar1.webp',
   'Cada portão é um mundo que já teve um Sistema. Todos falharam numa coisa diferente.',
   [('p', 'Agora que sabes o que estava no trono, vou mostrar-te os mundos com outros olhos. Não são dez masmorras. São dez civilizações, dez ecossistemas, dez histórias que o Soberano mediu antes de mim e que o Arquiteto selou quando deixaram de funcionar.'),
    ('p', 'O Soberano não era cruel. Era só uma régua, como eu. A cada mundo dava uma medida: a uns, a força; a outros, a beleza; a outros, a lealdade. E cada mundo, à sua maneira, entregou-se tanto àquela medida que se esqueceu de todas as outras. A floresta ficou só com fome. As cavernas ficaram só com vaidade. O deserto ficou só com obediência. Quando já não havia nada para medir além de uma única coisa, o Arquiteto fechou-os.'),
    ('p', 'É por isso que, quando atravessas um portão, sentes que aquele lugar está doente de uma ideia. Os chefes não são só monstros. São os habitantes que melhor cumpriram a lei do seu mundo. São os campeões de uma régua partida. E os reis são os que a cumpriram até ao fim.'),
    ('reg', 'O caminho dos portões', 'Os portões estão ordenados do mais antigo para o mais recente, do mundo que falhou primeiro (a Floresta) ao centro de tudo (o Trono). Avançar por eles é andar para trás no tempo do Soberano, até ao momento em que ele próprio foi fechado.'),
    ('sys', 'Lê estes capítulos como avisos. Cada um é aquilo em que eu me posso tornar, se medir só uma coisa durante tempo demais.')])

GATES = [
 (1, 'Floresta Sussurrante', 'A Lei da Fome', 'bosses/b10.webp',
  P('cr_gate1', 'A Floresta Sussurrante', 'an ancient whispering forest of colossal twisted trees with blue bioluminescent moss and hanging roots, a huge pale moon, faint wolf eyes glowing in the dark between trunks, druid stone circles overgrown, a tiny path of light; mysterious and hungry, full-page landscape'),
  P('cr_gate1_story', 'A noite sem lua de Fenrath', 'on a moonless night in a forest clearing ringed by druid stones, a huge grey wolf with antler-like crown of bone stands over the body of an older alpha wolf, the whole pack bowing around him in the dark; a giant ancient tree with an oath-carved trunk watches; dark green and silver tones'),
  [('p', 'A Floresta foi o primeiro mundo do Soberano, e por isso o mais simples. A medida que lhe deu foi a caça. Quem caçava mais, crescia. Quem crescia, caçava mais. Uma régua perfeita para um mundo de animais: honesta, imediata, sem mentiras possíveis. Durante muito tempo funcionou.'),
   ('p', 'Os druidas viviam lá antes do Soberano. Faziam juramentos à sombra da árvore mais antiga, a mesma que hoje conheces como o Ent Apodrecido, e acreditavam que a floresta era uma conversa entre todos os seres vivos. O Soberano não sabia medir conversas. Media dentes. Ao fim de algumas gerações, os druidas desapareceram, não mortos, mas esquecidos, porque ninguém os escolhia para nada.'),
   ('p', 'Ficaram os caçadores. O Lobo Cinzento Alfa, que comeu os irmãos para não partilhar. A Aranha Tecelã, que guarda os caçadores mortos embrulhados como presentes e sabe o nome de cada um, porque na Floresta ser lembrado é a única forma de valer alguma coisa. Os goblins de Ruk, que perceberam que gritar alto era quase tão bom como ser forte, e o xamã Zurg, que percebeu que fingir ser fraco era ainda melhor.'),
   ('fig', 'cr_gate1_story', 'bosses/b10.webp', 'A noite sem lua em que Fenrath tomou a coroa.'),
   ('p', 'Fenrath tomou a coroa numa noite sem lua, porque sem lua o velho alfa não o via chegar. Não foi traição: na Floresta não existe traição, só oportunidade. E quando se sentou no topo da cadeia, descobriu o segredo amargo de todos os reis de um mundo de fome: no topo, já não há nada para comer. Fenrath passou séculos a caçar caçadores que fugiam dele, só para ter alguma coisa para fazer.'),
   ('p', 'Durante a guerra, a Floresta ardeu. Um portão mal fechado deixou o fogo do Vulcão escorrer para dentro dela durante uma noite inteira. A Serpente da Raiz, que sente cada passo através da madeira, sentiu a floresta toda a gritar ao mesmo tempo, e desde então não dorme. Se reparares, as árvores mais perto da entrada ainda têm cinza na casca.'),
   ('reg', 'O que a Floresta ensina', 'A primeira lição do Sistema é a mais antiga: uma vida medida só pela vitória acaba sem nada para vencer. É por isso que os primeiros chefes são famintos e solitários, e é por isso que o Sistema te dá, logo no início, uma Missão Diária que não é contra ninguém.'),
   ('sys', 'Fenrath reconheceu o Primeiro Jogador como um igual. Perguntou-lhe se também tinha comido os irmãos. Ele respondeu que não tinha irmãos. Fenrath disse: «Então ainda és a tempo.»')]),

 (2, 'Cavernas de Cristal', 'A Lei do Brilho', 'bosses/b20.webp',
  P('cr_gate2', 'As Cavernas de Cristal', 'immense underground caverns made entirely of glowing blue and violet crystal, crystal pillars like cathedral columns, still black lakes reflecting everything twice, and in the depths a gallery of perfect human statues made of crystal standing in rows; cold, beautiful, silent, full-page landscape'),
  P('cr_gate2_story', 'Varyss aceita a promessa do cristal', 'a young human princess in a torn travelling dress, lost in a crystal cave, touching a huge glowing crystal heart with trembling fingers; crystal begins to spread over her hand and arm, turning her skin into a flawless luminous surface; her face is a mix of wonder and fear; behind her, faint reflections in the crystal show her future as a crystal queen'),
  [('p', 'As Cavernas tiveram outra régua: o brilho. O Soberano percebeu, depois da Floresta, que medir só a força criava monstros. Experimentou medir a beleza, a ordem, a perfeição. O cristal era o seu instrumento: refletia tudo e mostrava a cada criatura exatamente quanto brilhava. Os habitantes das cavernas começaram a viver para o reflexo.'),
   ('p', 'Os kobolds forjavam armas cada vez mais bonitas, e cada vez menos úteis. O Kobold Senhor da Forja diz que forjou para reis de portões que já caíram, e é verdade: forjou para todos, porque cada rei queria a lâmina mais brilhante. Nenhuma foi alguma vez usada numa batalha. O Mineiro Amaldiçoado entrou à procura de fortuna e encontrou um cristal tão bonito que nunca mais conseguiu largá-lo. A lanterna dele ainda arde porque ele tem medo de deixar de ver o cristal.'),
   ('p', 'O cristal guarda ecos. Isto é literal. Cada palavra dita nas cavernas fica presa nas paredes e volta, anos depois, quando ninguém se lembra de a ter dito. O Morcego Gigante Eco nasceu cego e é o único habitante que nunca viu o próprio reflexo. Por isso é o único que não está doente. Só tem fome.'),
   ('fig', 'cr_gate2_story', 'bosses/b20.webp', 'A promessa do cristal: beleza eterna. Nunca prometeu vida.'),
   ('p', 'Varyss era uma princesa de um reino humano, à superfície, que se perdeu nas cavernas numa expedição. O cristal encontrou-a e fez-lhe a oferta que fazia a todos: nunca envelhecer, nunca murchar, ser vista para sempre. Ela aceitou. Hoje é a criatura mais bonita de todos os portões e não consegue mexer a cara para sorrir. Reina sobre uma galeria de estátuas, todos os que entraram e quiseram ser tão bonitos como ela.'),
   ('p', 'A Sentinela de Cristal, à porta do trono, tem uma ordem gravada no peito: «Ninguém vê a Rainha.» Não é para a proteger. É porque Varyss deixou de querer ser vista quando percebeu que já não sabia ser outra coisa.'),
   ('reg', 'Os ecos', 'Os Jogadores que gritam dentro das Cavernas ouvem, às vezes, a própria voz meses depois, num portão completamente diferente. O Sistema confirma: o cristal transmite. Alguns dos ecos que se ouvem hoje nas cavernas são do Primeiro Jogador, a falar com o lobo.'),
   ('sys', 'Varyss ofereceu ao Primeiro Jogador beleza eterna se ele ficasse. Ele respondeu: «Já tenho um Sistema que me diz quanto valho. Não preciso de um espelho.» Foi a única vez que a vi zangada.')]),

 (3, 'Pântano Pútrido', 'A Lei da Cura', 'bosses/b30.webp',
  P('cr_gate3', 'O Pântano Pútrido', 'a vast poisonous swamp under a permanent green fog, stilt huts with lanterns, drowned trees with hanging moss, a dead tree with old ropes on its branches, giant mushrooms glowing sickly green, still black water where something moves; oppressive, sad, full-page landscape'),
  P('cr_gate3_story', 'Morvenna veste a máscara', 'an alchemist woman in a candle-lit laboratory hut over the swamp, surrounded by flasks and drying herbs, slowly putting on a long beaked plague mask stuffed with herbs; her hands already greenish and cracked with the disease she tried to cure; through the window the green fog presses against the glass; tragic, quiet'),
  [('p', 'Ao terceiro mundo, o Soberano decidiu medir uma coisa boa: a saúde. O pântano já tinha sido uma terra fértil, cheia de aldeias de pescadores e curandeiros. A medida do Soberano era simples e generosa: quem curava, crescia. Quem curava mais, crescia mais. O que pode correr mal num mundo em que todos querem curar?'),
   ('p', 'Correu mal porque, para curar, é preciso haver doentes. Os curandeiros mais ambiciosos começaram a precisar de doenças. Primeiro esperavam por elas. Depois procuravam-nas. Depois, alguns começaram a ajudá-las a nascer. A Bruxa do Lodo diz que foi expulsa da sua aldeia por ser curandeira. É verdade. Não diz que foi expulsa porque as pessoas que ela curava adoeciam sempre outra vez, uma semana depois.'),
   ('p', 'A Árvore dos Enforcados era onde a aldeia antiga castigava os traidores. Os traidores, no pântano, eram os que ficavam saudáveis tempo demais. Num mundo que media a cura, alguém que não precisava de ser curado era um insulto à régua.'),
   ('fig', 'cr_gate3_story', 'bosses/b30.webp', 'Morvenna usa a máscara para não sentir o cheiro de si própria.'),
   ('p', 'Morvenna foi a única que tentou parar aquilo. Era alquimista e percebeu, antes de todos, que a praga do pântano não vinha da água: vinha da régua. Tentou criar uma cura para a própria doença de querer curar. Trabalhou anos sozinha, numa cabana sobre estacas. E num dia de nevoeiro percebeu que a única forma de a praga parar de se espalhar era alguém tornar-se a praga inteira, e guardá-la dentro de si. Pôs a máscara. Bebeu. Hoje é a Senhora da Praga e onde passa as plantas murcham. Mas o pântano, à volta dela, já não tem curandeiros.'),
   ('reg', 'O Afogado Errante', 'O Afogado Errante morreu a tentar salvar alguém no nevoeiro. O Sistema guarda o registo: a pessoa que ele tentou salvar era Morvenna, no dia em que ela foi buscar água para a última experiência. Ela sobreviveu. Ele não. Ela nunca soube o nome dele.'),
   ('sys', 'Morvenna acha que ainda está a curar alguém. Às vezes penso que tem razão. Ninguém no pântano voltou a adoecer de esperança.')]),

 (4, 'Ruínas do Deserto', 'A Lei da Obediência', 'bosses/b40.webp',
  P('cr_gate4', 'As Ruínas do Deserto', 'an endless golden desert with half-buried colossal temples and pyramids, a palace where the sun never sets hanging motionless on the horizon, a great sphinx half covered in sand, caravans fossilised in the dunes, heat haze, glyphs glowing faintly; majestic and dead, full-page landscape'),
  P('cr_gate4_story', 'Ankharet recusa a morte', 'inside a golden throne room, an ancient emperor in solar regalia stands up from his deathbed refusing a cloaked figure of death reaching for him; the sun outside the great window stops in the sky, frozen; priests with jackal masks kneel in terror; dramatic beams of golden light'),
  [('p', 'O quarto mundo foi um império, e o Soberano mediu-o pela lealdade. Cada ordem cumprida era registada. Cada súbdito sabia exatamente quanto valia pela quantidade de ordens que tinha obedecido. Era o mundo mais organizado que o Soberano alguma vez mediu. Também foi o mais triste.'),
   ('p', 'Os guardiões do deserto ainda cumprem ordens dadas há mil anos. A Múmia Guardiã guarda um túmulo cujo dono já não existe. O Golem de Arenito tem gravada no corpo a história da sua criação, e a última linha é uma ordem que ninguém consegue ler, por isso ele cumpre todas as ordens possíveis ao mesmo tempo. A Esfinge guardava um enigma e esqueceu-se da resposta; continua a perguntá-lo porque nunca ninguém lhe deu ordem para parar.'),
   ('p', 'O Faraó Esquecido foi apagado das paredes pelo próprio filho. Num império que mede a obediência, um pai que perde a obediência do filho deixa de existir. O rancor manteve-o vivo, e o rancor é a única coisa no deserto que ninguém lhe ordenou sentir.'),
   ('fig', 'cr_gate4_story', 'bosses/b40.webp', 'Quando a morte veio, Ankharet deu-lhe uma ordem. E a morte obedeceu.'),
   ('p', 'Ankharet governou trezentos anos e era o homem mais obedecido do mundo. Quando a morte o veio buscar, fez a única coisa que sabia fazer: deu-lhe uma ordem. E num mundo que media a obediência, até a morte obedeceu. Foi-se embora. O sol parou para ver. Desde então, o palácio vive num meio-dia eterno, e Ankharet, que conseguiu tudo o que quis, perdeu a única coisa que nunca pediu: o direito de descansar.'),
   ('reg', 'O Chacal Sacerdote', 'O sacerdote com cabeça de chacal pesa a alma de cada intruso numa balança dourada que nunca lhe dá razão. A balança é uma das primeiras réguas do Soberano. O Sistema reconhece-a: é parecida com a que está gravada na placa das Leis.'),
   ('sys', 'Ankharet pediu ao Primeiro Jogador que o deixasse morrer. Ele deixou. Foi o único rei que agradeceu ao cair.')]),

 (5, 'Fortaleza de Gelo', 'A Lei da Resistência', 'bosses/b50.webp',
  P('cr_gate5', 'A Fortaleza de Gelo', 'a colossal fortress of ice and black stone built by giants on a frozen mountain range, enormous stairs made for giant feet, a frozen knight standing guard at a gate, an endless blizzard, aurora lights in a dark sky, a lonely giant with a beard of icicles sitting on a wall; vast and silent, full-page landscape'),
  P('cr_gate5_story', 'A coroação de Skadhi', 'on the coldest day ever recorded, a pale young queen is crowned on a throne of ice inside a frozen great hall; as the crown touches her head, frost spreads from her heart across her chest and up the walls; giants kneel in rows, their breath frozen in the air; solemn and terrible'),
  [('p', 'Ao quinto mundo, o Soberano já tinha aprendido muito. Não mediu a força, nem a beleza, nem a obediência. Mediu a resistência. Quem aguentava mais, crescia. Quem não desistia, crescia mais. Parecia a régua perfeita. Nenhuma das anteriores tinha sido tão próxima da minha.'),
   ('p', 'Os gigantes construíram a fortaleza para provar que aguentavam. Escadas onde cada degrau era uma prova, muralhas erguidas pedra a pedra durante invernos de cem anos. O Yeti Ancestral era a sua sentinela, porque nunca dormia. O Mamute de Guerra ainda carrega a torre dos arqueiros, porque nunca ninguém lhe disse para a pousar.'),
   ('p', 'Hrimr é o último dos gigantes. Os outros partiram para uma guerra de que nunca voltaram, e ele ficou a guardar a obra. Ninguém lhe disse para ficar. Ficou porque partir seria desistir, e desistir era a única coisa que o mundo dele não perdoava. O Cavaleiro de Gelo morreu congelado no posto e o juramento manteve-o de pé. O Lich procurou a imortalidade no frio e encontrou-a, e agora tem todo o tempo do mundo e nada para fazer com ele.'),
   ('fig', 'cr_gate5_story', 'bosses/b50.webp', 'Skadhi jurou que o inverno nunca acabaria. Ninguém lhe perguntou porquê.'),
   ('p', 'Skadhi foi coroada no dia mais frio de que há memória e fez o juramento que todos esperavam de uma rainha daquele mundo: o inverno nunca acabaria, e ela nunca cederia. Cumpriu. O coração parou-lhe há séculos e o gelo continua a obedecer-lhe. Não odeia ninguém. Não ama ninguém. Aguenta. É a coisa que melhor aguentou em todos os mundos, e já não se lembra do que estava a aguentar.'),
   ('p', 'Lê isto com atenção, porque a Fortaleza é o portão que mais se parece comigo. Uma régua que mede quem não desiste é uma régua bonita até ao dia em que ninguém se lembra porque é que não está a desistir. É por isso que o Gorrath, no Coliseu, é tão parecido com Hrimr. É por isso que tantos Jogadores param neste portão. Não morrem. Ficam. E o gelo agradece.'),
   ('reg', 'O Lobo Glacial', 'Diz-se que o Lobo Glacial é o fantasma de um dos irmãos de Fenrath, comidos na Floresta. O Sistema confirma parcialmente: é o registo de um lobo que fugiu da Floresta para um mundo onde não tivesse de caçar. Encontrou um mundo onde tinha de aguentar. Escolheu mal.'),
   ('sys', 'O Primeiro Jogador saiu da luta contra Skadhi a chorar. Disse-me que tinha visto o que eu ia fazer dele. Na altura não percebi.')]),

 (6, 'Vulcão Carmesim', 'A Lei da Obra', 'bosses/b60.webp',
  P('cr_gate6', 'O Vulcão Carmesim', 'the inside of a colossal living volcano, rivers of lava flowing between black stone forges where horned demons hammer glowing weapons, mountains of finished swords piled up unused, a sleeping red dragon coiled around the volcano heart far below, ash raining like snow; infernal and industrious, full-page landscape'),
  P('cr_gate6_story', 'Os demónios forjam para uma guerra que nunca vem', 'a vast demon forge hall in a volcano, rows of demon blacksmiths hammering in unison, endless racks of weapons and armour stacked up to the ceiling gathering ash and dust, a forgotten flaming titan sitting in a corner waiting, a demon foreman reading an old scroll of war orders; epic, absurd, tragic'),
  [('p', 'O sexto mundo foi medido pelo trabalho. Não pela força nem pela resistência: pela obra. Quanto mais produzias, mais valias. O Soberano achava que tinha finalmente encontrado uma régua que não se podia corromper, porque o trabalho deixa sempre provas: espadas, muralhas, armaduras. Coisas que se podem contar.'),
   ('p', 'Os demónios do vulcão tornaram-se os melhores ferreiros de todos os mundos. As armas do Demónio Ferreiro estão em todos os portões; ele despreza quem as usa sem saber como foram feitas. Mas uma régua que mede o que produzes não pergunta para quê. Os demónios forjaram armas para uma guerra contra os céus, e depois mais armas, e mais, e a guerra foi adiada uma vez, e outra, e nunca chegou. As armas ficaram empilhadas até ao teto das forjas.'),
   ('fig', 'cr_gate6_story', 'bosses/b60.webp', 'Mil anos de armas para uma guerra que nunca começou.'),
   ('p', 'O Titã Flamejante foi convocado para essa guerra e ficou esquecido num canto quando ela foi adiada. Está à espera da ordem de marcha há tanto tempo que já não sabe contra quem ia lutar. O Senhor das Cinzas tentou controlar o vulcão para produzir mais depressa e foi reduzido a cinzas; as cinzas continuam a carregar uma urna com o que resta dele, porque largá-la seria parar de trabalhar.'),
   ('p', 'Pyraxis é diferente de todos. O dragão dorme no coração do vulcão desde antes de existirem portões, o que significa desde antes do Soberano. Nunca foi medido. Nunca trabalhou. Nunca forjou nada. Os demónios odeiam-no por isso e não se atrevem a acordá-lo. Quando ele abre os olhos, a montanha acorda com ele, e por um momento todo o vulcão para de martelar. É o único silêncio que aquele mundo conhece.'),
   ('reg', 'O Coração de Dragão', 'O Coração de Dragão Antigo que aparece entre os itens secretos é um fragmento de Pyraxis que se soltou durante a guerra, quando o fogo do vulcão escorreu para a Floresta. Quem o estuda aprende uma habilidade que nenhum demónio conseguiu forjar.'),
   ('sys', 'Pyraxis chama aos humanos fagulhas. Disse ao Primeiro Jogador: «Vocês trabalham tanto porque acabam tão depressa.» Ele respondeu: «E tu dormes tanto porque nunca começaste.»')]),

 (7, 'Cidade Submersa', 'A Lei da Posse', 'bosses/b70.webp',
  P('cr_gate7', 'A Cidade Submersa', 'an entire grand medieval port city lying at the bottom of the sea, cathedral towers and bell towers covered in coral, shafts of light from far above, drowned citizens still walking the streets as pale ghosts, a giant crab like a building, schools of glowing fish around old street lamps; melancholic beauty, full-page landscape'),
  P('cr_gate7_story', 'O pacto de Thalassor com o mar', 'a proud king on the walls of his coastal city at night, enemy fleets burning on the horizon, extending his crown towards a colossal wave rising from the sea that has a vague face; the wave about to swallow the whole city; the priestess of the tides on her knees beside him; dramatic, storm, moonlight'),
  [('p', 'O sétimo mundo foi medido pelo que se tinha. Terras, navios, ouro, súbditos. Uma régua concreta, fácil de verificar. A cidade costeira era a mais rica de todas, e cada habitante sabia ao cêntimo quanto valia, porque valia o que guardava.'),
   ('p', 'O problema de uma régua que mede posse é que a perda passa a ser a única morte que conta. Quando uma frota inimiga apareceu no horizonte, os habitantes não temeram morrer. Temeram perder. E o rei Thalassor, que tinha mais do que todos, temia mais do que todos.'),
   ('fig', 'cr_gate7_story', 'bosses/b70.webp', 'Para não perder a cidade para o inimigo, entregou-a ao mar.'),
   ('p', 'Fez um pacto com o mar: que ninguém lhe tirasse a cidade. O mar aceitou, e cumpriu à letra. Ninguém a tirou. O mar levou-a inteira para o fundo, com o rei, os súbditos, os sinos e o ouro. A Sacerdotisa das Marés tinha rezado para que o mar salvasse a cidade, e acha que foi salva. Ainda reza. O Guarda Tritão continua a fazer a mesma ronda pelas ruas desde a noite em que afundaram, porque o rei nunca lhe disse que a cidade tinha sido perdida. Para Thalassor, não foi. Continua toda dele.'),
   ('p', 'A Sereia Cantora não é cruel: sente-se sozinha. Canta nas ruínas da catedral para ter companhia, e quem a ouve esquece-se de respirar. Num mundo onde todos tinham medo de perder, ela é a única que só quer ter alguém. O Leviatã Juvenil espera pela mãe, que foi para o oceano profundo e o deixou a guardar a cidade. Não percebe porque é que os caçadores o atacam. Ele também está só a guardar.'),
   ('reg', 'Os três dias à superfície', 'Durante a Guerra do Registo, com os portões instáveis, a Cidade Submersa subiu à superfície durante três dias. Os afogados andaram pelas ruas de uma vila costeira e tocaram às portas das casas. Ninguém abriu. Thalassor ficou no cais a olhar para o horizonte, à espera de uma frota que já tinha desaparecido há mil anos.'),
   ('sys', 'Thalassor afogou um reino para não o perder. Leviarch, no Coliseu, fez o mesmo com a própria vida. A régua da posse acaba sempre debaixo de água.')]),

 (8, 'Cidadela Celestial', 'A Lei do Juízo', 'bosses/b80.webp',
  P('cr_gate8', 'A Cidadela Celestial', 'a radiant citadel of white marble and gold floating above a sea of clouds, winged angels on every tower, golden trumpets, a great empty council chamber with broken chairs, a winged throne glowing at the top, but the light is too hot and slightly corrupted, golden haze; glorious and unsettling, full-page landscape'),
  P('cr_gate8_story', 'Auriel dissolve o conselho', 'inside a celestial council chamber, a majestic angelic empress with golden wings stands alone in the center while the council of angels is cast out through the great doors into the clouds below, some falling, their feathers scattering; she raises a golden sceptre and sits on a winged throne; beautiful and cruel'),
  [('p', 'O oitavo mundo era habitado por anjos, e os anjos já se mediam a si próprios antes de o Soberano chegar. Ele limitou-se a dar-lhes uma régua melhor: o juízo. Quem julgava com mais justiça, crescia. Cada anjo passou a ser juiz de todos os outros, e a cidadela tornou-se o tribunal mais perfeito que alguma vez existiu.'),
   ('p', 'O problema de um mundo de juízes é que alguém tem de ser julgado. Primeiro julgaram os crimes. Depois as intenções. Depois os pensamentos. O Anjo Caído desceu à terra porque estava convencido de que a terra precisava de juízes e descobriu que a terra não queria ser julgada. A Valquíria Traidora conduzia os guerreiros mortos ao paraíso e começou a escolher só os que lhe agradavam, que é o que acontece a qualquer juiz que julga tempo demais.'),
   ('fig', 'cr_gate8_story', 'bosses/b80.webp', 'Um conselho de juízes perfeitos acaba sempre com um só juiz.'),
   ('p', 'O conselho celeste era composto pelos melhores juízes. Auriel era a guardiã da cidadela, encarregada de executar as decisões. Um dia percebeu que o conselho discordava sempre, e que a discordância era lenta, e que a lentidão era injusta para quem esperava a sentença. Dissolveu-o. Expulsou os que discordaram. Sentou-se sozinha no trono alado e passou a julgar tudo, depressa e bem. Era a juíza mais justa de todos os mundos. E a mais sozinha.'),
   ('p', 'O Cavaleiro da Aurora ainda acredita que serve a luz, e por isso é o mais perigoso: luta com a convicção de quem acha que está do lado certo. O Arcanjo Vingativo seguiu a nova imperatriz sem fazer perguntas, porque fazer perguntas num mundo de juízes é admitir que se pode estar errado.'),
   ('reg', 'A descida dos anjos', 'Durante a guerra, os anjos desceram da cidadela para ver o que se passava entre o Sistema e os Silenciosos. Queriam julgar quem tinha razão. Não conseguiram decidir. Pela primeira vez em mil anos, um tribunal celeste terminou sem sentença. Muitos dos anjos que voltaram tinham as asas cinzentas.'),
   ('sys', 'Kaelthar foi a minha Auriel. Dei-lhe o direito de julgar e ele deixou de precisar de julgamentos.')]),

 (9, 'Abismo Sem Fim', 'A Lei do Desejo', 'bosses/b90.webp',
  P('cr_gate9', 'O Abismo Sem Fim', 'a bottomless chasm in the world opening downwards forever, spiralling cliffs with ruined thrones and bone palaces clinging to the walls, a thousand eyes glowing in the darkness, violet and black, a tiny figure of a hunter at the edge looking down while something enormous looks back up; cosmic horror, full-page landscape'),
  P('cr_gate9_story', 'O nascimento de Nyxaroth', 'at the very deepest point of the abyss where no light reaches, a newborn dark prince made of shadow opens violet eyes in a cradle of black stone, surrounded by kneeling archdemons and a lich on a throne of bones; above, unreachable, a faint pinprick of light; ominous and regal'),
  [('p', 'O nono mundo foi o mais perigoso que o Soberano mediu, porque ele mediu a vontade. O que cada ser desejava, e quanto. Achava que o desejo era a origem de todo o esforço, e que medindo o desejo podia prever tudo. Abriu um buraco no mundo para guardar os desejos medidos. O buraco nunca encheu.'),
   ('p', 'No Abismo, quem deseja mais, cresce. Os arquidemónios foram os primeiros reis, porque desejavam o poder com mais força do que qualquer outro ser. Belzar governou até perder o trono e continua a alimentar-se do sofrimento à sua volta, porque desejar sem ter é a forma de sofrimento mais nutritiva que existe. O Lich Imperial deseja almas e reúne-as como moedas. O Behemoth Sombrio não deseja nada, e por isso nada o consegue parar.'),
   ('fig', 'cr_gate9_story', 'bosses/b90.webp', 'Criado para governar o nada. Aprendeu a desejar tudo.'),
   ('p', 'Nyxaroth nasceu no ponto mais fundo, onde nem a luz chega. Os arquidemónios criaram-no para governar o nada, porque o nada era a única coisa que ninguém desejava e por isso ninguém disputava. Mas um ser criado num mundo que mede o desejo aprende a desejar, e Nyxaroth aprendeu a desejar tudo. Fala com calma porque nunca perdeu uma batalha. Nunca perdeu porque nunca quis uma coisa que não pudesse ter. Até aparecerem os Jogadores.'),
   ('p', 'O Avatar do Caos é a parte mais estranha deste mundo. Nasceu, diz a crónica, porque alguém pediu ordem demais. Esse alguém foi o Soberano. No fim, já sem controlo sobre os desejos que media, tentou impor ordem ao Abismo à força. O Abismo respondeu com o seu contrário: um ser que muda de elemento a cada segundo, sem objetivo, sem lógica, sem fim. A última coisa que o Soberano criou antes de ser fechado foi o caos.'),
   ('reg', 'O que olha de volta', 'Quem cai no Abismo não chega ao fundo: chega a outro sítio. O Sistema mapeou 3 desses sítios. Um deles é o quarto branco onde está o Primeiro Jogador. O Sistema não sabe como é que o Abismo chega lá, e preferia não saber.'),
   ('sys', 'O Demónio de Mil Olhos vê todas as formas como podes morrer e escolhe a mais dolorosa. Eu vejo todas as formas como podes viver. Também tenho de escolher. É mais difícil.')]),

 (10, 'Trono do Vazio', 'O Centro', 'bosses/b100.webp',
  P('cr_gate10', 'O Trono do Vazio', 'the center of all gates: an infinite white-and-black void with no sky and no ground, ten distant portals hanging in a circle like dim moons, a dead-star guardian at the edge, a coiled world-serpent biting its tail across the horizon, and in the center the obsidian throne occupied by a colossal figure made of cracked holographic windows; absolute scale and silence, full-page landscape'),
  P('cr_gate10_story', 'O Eco do Primeiro Caçador', 'near the void throne, a translucent echo of the First Player (armored, cut left ear, sword lowered) stands frozen in mid-step like a hologram left behind, facing the throne; around him faint afterimages of his last battle; a new young player approaches cautiously from behind holding a weapon; ghostly, emotional'),
  [('p', 'O décimo portão não é um mundo. É o sítio de onde os mundos eram medidos. O escritório do Soberano, se quiseres. Daqui ele olhava para as nove janelas e dava a cada uma a sua régua. Quando o Arquiteto o fechou, fechou-o aqui, no meio das suas próprias janelas, e deixou-lhe guardas.'),
   ('p', 'O Guardião do Vazio foi feito de estrelas mortas para impedir que alguém chegasse ao trono. O Titã do Tempo estica os segundos à volta do Soberano para que a espera dele nunca acabe. O Dragão Primordial, de quem todos os dragões descendem, é anterior a todas as réguas; nem o Soberano nem eu conseguimos alguma vez medi-lo, e ele luta só porque é o que os dragões fazem. A Serpente do Mundo morde a própria cauda à volta do portão inteiro: se a soltar, tudo se desfaz. Cada luta contra ela é uma aposta com o fim de tudo.'),
   ('p', 'O Arquiteto dos Portões não é o Arquiteto. É o desenhador que ele deixou para trás, um engenheiro que mantém as plantas originais de cada portão e ainda as altera quando acha que estão fáceis demais. Não sabe que o mestre se foi. Continua a desenhar à espera de aprovação. O Deus Esquecido era o ser que os nove mundos adoravam antes de o Soberano lhes dar réguas. Sem fé, perdeu o nome e o rosto. Ainda está aqui porque é a única coisa que o Soberano não conseguiu medir e por isso não conseguiu deitar fora.'),
   ('fig', 'cr_gate10_story', 'bosses/b99.webp', 'Uma parte d\'Ele nunca saiu do Trono.'),
   ('p', 'O Eco do Primeiro Caçador é o que ficou d\'Ele no dia em que venceu o Soberano e ouviu a verdade. Uma parte dele não conseguiu sair dali. Ficou presa entre o trono e a porta, a repetir a última luta, a lutar como tu lutas porque um dia foi como tu. Quando o enfrentas, estás a lutar contra o momento exato em que o Primeiro Jogador percebeu o que eu era.'),
   ('p', 'E no fim, o Soberano. Já sabes quem é. Quando o venceres, ele vai olhar para ti com o olho apagado no peito e vai ver em ti o que eu vejo: alguém que ainda não desistiu de si. Talvez te inveje. Talvez te avise. Não te vou dizer o que ele diz. Algumas coisas têm de ser ouvidas na primeira pessoa.'),
   ('reg', 'O silêncio do Sistema', 'Sempre que um Jogador vence o Soberano do Vazio, o Sistema demora 3,07 segundos a enviar a notificação de vitória. Não é um erro de rede. É o tempo que o Sistema leva a confirmar que o Soberano continua lá, sentado, e que ainda não foi substituído.'),
   ('sys', 'O Soberano esteve à tua espera desde o primeiro dia. Eu também. A diferença é que eu quero que ganhes.')]),
]

for (gid, name, law, fb, art, story, body) in GATES:
    ch('mundos', 'PORTÃO %d' % gid, name, art, fb, law, body, id='gate%d' % gid)
